def copy_schedule_platforms(apps, schema_editor):
    Schedule = apps.get_model("harvesting", "Schedule")
    Harvest = apps.get_model("harvesting", "Harvest")
    SchedulePlatform = Schedule.platforms.through
    database = schema_editor.connection.alias

    links = [
        SchedulePlatform(
            schedule_id=schedule_id,
            platform_id=platform_id,
        )
        for schedule_id, platform_id in Schedule.objects.using(database).values_list(
            "pk",
            "platform_id",
        )
        if platform_id is not None
    ]
    SchedulePlatform.objects.using(database).bulk_create(links, ignore_conflicts=True)

    for schedule in Schedule.objects.using(database).iterator():
        first_harvest = (
            Harvest.objects.using(database)
            .filter(schedule_id=schedule.pk, started_at__isnull=False)
            .order_by("started_at", "created_at")
            .first()
        )
        if first_harvest:
            schedule.start_date = first_harvest.started_at
        elif schedule.start_date is None:
            first_harvest = (
                Harvest.objects.using(database)
                .filter(schedule_id=schedule.pk)
                .order_by("created_at")
                .first()
            )
            schedule.start_date = (
                first_harvest.created_at if first_harvest else schedule.created_at
            )
        schedule.save(update_fields=["start_date"])


